    /// <summary>
    /// The Pre-Budget Data and Report page fetches demand/appendix screens via AJAX (fetch with
    /// X-Requested-With: XMLHttpRequest) and injects the returned HTML into a container on the
    /// page, instead of a full page navigation per dropdown change. Every action on this
    /// controller that returns a View - AppendixEntry itself and every SaveAppendixX/
    /// FreezeAppendixX/DeleteAppendixX action, whether it renders directly or redirects back to
    /// AppendixEntry - needs to come back as a bare fragment (no sidebar/header) in that case, so
    /// this is handled once, centrally, instead of touching every one of those ~90 actions
    /// individually. See Areas/PreBudgetMeeting/Views/_ViewStart.cshtml for the other half.
    /// </summary>
    public override void OnActionExecuted(ActionExecutedContext context)
    {
        if (IsAjaxRequest() && context.Result is ViewResult viewResult)
        {
            viewResult.ViewData["Layout"] = string.Empty;
        }

        base.OnActionExecuted(context);
    }

    private bool IsAjaxRequest() =>
        string.Equals(Request.Headers["X-Requested-With"], "XMLHttpRequest", StringComparison.OrdinalIgnoreCase);

    // App: Pre Budget Meeting | Module: Pre Budget Meeting
    // Select-Demand-and-Appendix screen (replaces the old app's SelectAppendix.aspx / sp_Select_Demands_Template).
    [HttpGet]
    public async Task<IActionResult> PreBudgetDataandReport(int? demandId, CancellationToken ct)
    {
        ViewData["Title"] = "Pre-Budget Data and Report";
        ViewData["Breadcrumb"] = "Pre Budget Meeting / Data Entry / Pre-Budget Data and Report";

        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        var model = new PreBudgetSelectorViewModel
        {
            FinancialYear = session.FinancialYear,
            SelectedDemandId = demandId
        };

        var demandsResult = await _aimClient.GetMyDemandsAsync(session.Token, session.FinancialYear, ct);
        if (demandsResult.IsSuccess && demandsResult.Data != null)
        {
            model.Demands = demandsResult.Data.Demands;

            // Client report 2026-09-10 ("Demand dropdown showing 3 entries per demand"): AIM's
            // GetMyDemands only checks role-based visibility (M_MapUserRole) - it has no idea
            // whether PreBudget's own Appendix Allocation workflow has actually been set up for a
            // given Demand, and returns every Demand the user may see regardless. Narrow that list
            // down to only Demands with a real dbo.M_DemandAppendixAllocation row for this year -
            // see IAppendixService.GetAllocatedDemandIdsAsync's own doc comment for the exact fan-
            // out bug this replaces (a naive INNER JOIN there would have reproduced the same "N
            // entries per demand" symptom for any Demand with N allocated Appendixes). Fails open
            // (keeps AIM's full list) if this call itself fails, rather than showing no Demands at
            // all over a transient PreBudget-service hiccup.
            if (model.Demands.Count > 0)
            {
                var allocatedResult = await _preBudgetClient.GetAllocatedDemandIdsAsync(
                    session.Token, model.Demands.Select(d => d.DemandId), session.FinancialYear, ct);
                if (allocatedResult.IsSuccess && allocatedResult.Data != null)
                {
                    var allocatedIds = allocatedResult.Data.ToHashSet();
                    model.Demands = model.Demands.Where(d => allocatedIds.Contains(d.DemandId)).ToList();
                }
            }
        }
        else
        {
            model.StatusIsError = true;
            model.StatusMessage = demandsResult.Error?.Message ?? "Could not load your Demands. Please try again shortly.";
        }

        // Appendix list/status for a pre-selected demandId (e.g. a bookmarked URL) is fetched
        // client-side via GetAppendixOptions instead of here - the view no longer renders
        // Model.Appendices directly (see pre-budget-meeting.js), so fetching it twice (once here,
        // unused, and once via AJAX on page load) would just be wasted work.

        return View(model);
    }

    /// <summary>
    /// AJAX-only: populates the Appendix dropdown once a Demand is picked, without a full page
    /// reload. Returns the Code/Name/IsFrozen/IsTargetDateExpired/TargetDate shape.
    /// </summary>
    [HttpGet]
    public async Task<IActionResult> GetAppendixOptions(int demandId, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return Unauthorized();
        }

        var statusResult = await _preBudgetClient.GetAppendicesWithStatusAsync(session.Token, demandId, session.FinancialYear, ct);
        if (!statusResult.IsSuccess || statusResult.Data == null)
        {
            return Json(new { success = false, message = statusResult.Error?.Message ?? "Could not load appendices for the selected Demand." });
        }

        return Json(new
        {
            success = true,
            appendices = statusResult.Data.Select(a => new
            {
                code = a.Code,
                name = a.Name,
                isFrozen = a.IsFrozen,
                isNilSubmitted = a.IsNilSubmitted,
                isTargetDateExpired = a.IsTargetDateExpired,
                targetDate = a.TargetDate
            })
        });
    }

