    /// <summary>
    /// Central dispatcher for "Go to Entry Screen" — mirrors the old app's per-appendix .aspx
    /// pages, but as one action keyed by the FRS Roman-numeral Code instead of 22 separate routes.
    /// Only I/II/III-A have a real form built so far (see design doc §10/§11) — every other code
    /// gets the ComingSoon view rather than a broken/half-wired page.
    /// </summary>
    [HttpGet]
    public async Task<IActionResult> AppendixEntry(string code, int demandId, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        var appendix = await FindAppendixByCodeAsync(session.Token, session.FinancialYear, code, ct);
        var demandName = await ResolveDemandNameAsync(session, demandId, ct);

        ViewData["Breadcrumb"] = $"Pre Budget Meeting / Pre Budget Meeting / {appendix?.Name ?? code}";
        ViewData["Title"] = appendix?.Name ?? code;

        switch (code)
        {
            case "I":
                return View("AppendixI", await BuildAppendixIViewModelAsync(session, demandId, demandName, ct));
            case "I-A":
                return View("AppendixIA", await BuildAppendixIAViewModelAsync(session, demandId, demandName, ct));
            case "II":
                return View("AppendixII", await BuildAppendixIIViewModelAsync(session, demandId, demandName, ct));
            case "III":
                return View("AppendixIII", await BuildAppendixIIIViewModelAsync(session, demandId, demandName, ct));
            case "III-A":
                return View("AppendixIIIA", await BuildAppendixIIIAViewModelAsync(session, demandId, demandName, ct));
            case "III-B":
                return View("AppendixIIIB", await BuildAppendixIIIBViewModelAsync(session, demandId, demandName, ct));
            case "IV":
                return View("AppendixIV", await BuildAppendixIVViewModelAsync(session, demandId, demandName, ct));
            case "IV-A":
                return View("AppendixIVA", await BuildAppendixIVAViewModelAsync(session, demandId, demandName, ct));
            case "IV-B":
                return View("AppendixIVB", await BuildAppendixIVBViewModelAsync(session, demandId, demandName, ct));
            case "V":
                return View("AppendixVSummary", await BuildAppendixVSummaryViewModelAsync(session, demandId, demandName, ct));
            case "V-A":
                return View("AppendixVA", await BuildAppendixVAViewModelAsync(session, demandId, demandName, ct));
            case "V-B":
                return View("AppendixVB", await BuildAppendixVBViewModelAsync(session, demandId, demandName, ct));
            case "V-C":
                return View("AppendixVC", await BuildAppendixVCViewModelAsync(session, demandId, demandName, ct));
            case "VI":
                return View("AppendixVI", await BuildAppendixVIViewModelAsync(session, demandId, demandName, ct));
            case "VI-A":
                return View("AppendixVIA", await BuildAppendixVIAViewModelAsync(session, demandId, demandName, ct));
            case "VI-B":
                return View("AppendixVIB", await BuildAppendixVIBViewModelAsync(session, demandId, demandName, ct));
            case "VI-C":
                return View("AppendixVIC", await BuildAppendixVICViewModelAsync(session, demandId, demandName, ct));
            case "VI-D":
                return View("AppendixVID", await BuildAppendixVIDViewModelAsync(session, demandId, demandName, ct));
            case "VI-E":
                return View("AppendixVIE", await BuildAppendixVIEViewModelAsync(session, demandId, demandName, ct));
            case "VI-F":
                return View("AppendixVIF", await BuildAppendixVIFViewModelAsync(session, demandId, demandName, ct));
            case "VI-G":
                return View("AppendixVIG", await BuildAppendixVIGViewModelAsync(session, demandId, demandName, ct));
            case "VII-A":
                return View("AppendixVIIA", await BuildAppendixVIIAViewModelAsync(session, demandId, demandName, ct));
            case "VII-B":
                return View("AppendixVIIB", await BuildAppendixVIIBViewModelAsync(session, demandId, demandName, ct));
            // Client data correction 2026-09-10: dbo.M_Appendix.Code for this appendix changed
            // from "XI" to "X" ("X - Loan to Government Servants, etc."). 2026-09-14: completed
            // the rename across every C#/file/view/JS identifier and the DB table itself
            // (dbo.Appendix_X_LoansToGovtServants, was Appendix_XI_LoansToGovtServants) - no more
            // "XI"-named code anywhere for this appendix.
            case "X":
                return View("AppendixX", await BuildAppendixXViewModelAsync(session, demandId, demandName, ct));
            case "PA-ReceiptPayment":
                return View("AppendixPA", await BuildAppendixPAViewModelAsync(session, demandId, demandName, ct));
            default:
                ViewData["ComingSoonCode"] = code;
                ViewData["ComingSoonName"] = appendix?.Name ?? code;
                return View("AppendixComingSoon");
        }
    }

    /// <summary>
    /// Template-level Freeze button (client review 2026-08-05, item 3): freezes this Demand+Appendix
    /// for the session's financial year via dbo.PreBudgetSubmissionStatus, distinct from any
    /// row-level freeze an individual appendix's own records may separately support.
    /// </summary>
    /// <summary>
    /// Generic export for any appendix grid (added 2026-09-15, client instruction: "export
    /// functionality should depend on columns of grid being export, not hard-code... any update on
    /// grid columns should not change export functionality... if grid has colspan or rowspan for
    /// headers, export to excel and PDF should support it"). Every per-appendix ExportAppendixX
    /// action before this hand-maintained its own Columns/Rows list in C#, which drifts out of sync
    /// with the actual grid the moment someone edits the view without also updating the export code
    /// (exactly the bug fixed for Appendix III's export headers a few commits back) - this endpoint
    /// takes whatever wwwroot/js/grid-export.js scraped directly off the live &lt;table&gt; DOM
    /// (headers including any colspan/rowspan grouping, visible data rows respecting the Columns
    /// menu's current show/hide state and current sort, and which columns are right-aligned) and
    /// forwards it to the Reporting service completely unchanged - there is no appendix-specific
    /// code in this action at all, so it never needs touching again as any appendix's grid evolves.
    /// New appendixes should wire their Export button to grid-export.js instead of writing a new
    /// ExportAppendixX action; existing ones migrate opportunistically.
    /// </summary>
    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> ExportGrid([FromBody] GridExportRequestDto request, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null) return await ExpiredSessionRedirectAsync();

        var report = new TabularReportDto
        {
            Title = request.Title,
            Subtitle = request.Subtitle,
            ColumnGroups = request.ColumnGroups?.Select(g => new ReportColumnGroupDto { Label = g.Label, ColumnSpan = g.ColumnSpan }).ToList(),
            Columns = request.Columns,
            RightAlignedColumns = request.RightAlignedColumns,
            Groups = new List<ReportGroupDto> { new() { Rows = request.Rows } },
            FileName = request.FileName
        };

        var exportResult = request.Format?.ToLowerInvariant() switch
        {
            "excel" => await _reportingClient.ExportExcelAsync(session.Token, report, ct),
            "csv" => await _reportingClient.ExportCsvAsync(session.Token, report, ct),
            _ => await _reportingClient.ExportPdfAsync(session.Token, report, ct)
        };

        if (!exportResult.IsSuccess || exportResult.Data == null)
        {
            return StatusCode(500, new { message = exportResult.Error?.Message ?? "Could not generate the export. Please try again." });
        }

        var (contentType, extension) = request.Format?.ToLowerInvariant() switch
        {
            "excel" => ("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "xlsx"),
            "csv" => ("text/csv", "csv"),
            _ => ("application/pdf", "pdf")
        };
        return File(exportResult.Data, contentType, $"{report.FileName}.{extension}");
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> FreezeAppendixTemplate(int demandId, string code, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null) return await ExpiredSessionRedirectAsync();

        var appendix = await FindAppendixByCodeAsync(session.Token, session.FinancialYear, code, ct);
        if (appendix != null)
        {
            await _preBudgetClient.FreezeSubmissionAsync(session.Token, appendix.AppendixId, demandId, session.FinancialYear, ct);
        }

        // Bug fix 2026-08-06: was RedirectToAction, which meant a second round trip whose response
        // OnActionExecuted never saw (it only fragment-izes a ViewResult, not a RedirectResult) -
        // fetch() then rendered the FULL page (header/sidebar included) into #partialViewContainer,
        // which is what made the Demand/Appendix dropdowns above it look like they'd been wiped.
        // Every other Save/Freeze action in this file already returns the View directly for exactly
        // this reason - matching that here instead of redirecting.
        return await AppendixEntry(code, demandId, ct);
    }

    // ---------------------------------------------------------------------------------------
    // Appendix I: Budget and Expenditure Trends
    // ---------------------------------------------------------------------------------------

    /// <summary>
    /// Approved design (2026-07-29): a fixed 5-year grid (session FY's 5 preceding years) saved as
    /// one batch instead of one ad-hoc record at a time. Each row with an existing Id is updated;
    /// each row with no Id but at least one non-empty field is created; rows with no Id and
    /// nothing entered, or that are already frozen, are skipped.
    /// </summary>
    /// <summary>
    /// Rewritten 2026-09-09 for the drawer/grid redesign - previously posted the whole 5-year
    /// matrix (List&lt;AppendixIYearRowViewModel&gt;) in one submit; now posts a single record like
    /// every other redesigned appendix. FinancialYear is always forced to ActualYear server-side
    /// (never trusted from the client) since that's the only year this screen ever permits
    /// Add/Edit on - see AppendixIViewModel.ActualYear's own doc comment.
    /// </summary>
    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> SaveAppendixI(int demandId, SaveAppendixBudgetExpenditureTrendDto newRecord, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        var demandName = await ResolveDemandNameAsync(session, demandId, ct);
        var actualYear = GetPrecedingFinancialYears(session.FinancialYear, 3).FirstOrDefault() ?? session.FinancialYear;
        newRecord.DemandId = demandId;
        newRecord.FinancialYear = actualYear;

        var result = newRecord.Id.HasValue && newRecord.Id.Value > 0
            ? await _preBudgetClient.UpdateAppendixIAsync(session.Token, newRecord.Id.Value, newRecord, ct)
            : await _preBudgetClient.CreateAppendixIAsync(session.Token, newRecord, ct);

        var model = await BuildAppendixIViewModelAsync(session, demandId, demandName, ct);
        // "Input grid still not blank after Submit" (client testing feedback, 2026-08-24) - asp-for
        // renders from ModelState before the model; see AppendixIV.cs's matching comment. Only on
        // success - keep the user's typed values on the page if the save itself failed.
        if (result.IsSuccess)
        {
            ModelState.Clear();
        }
        model.StatusIsError = !result.IsSuccess;
        model.StatusMessage = result.IsSuccess
            ? (newRecord.Id.HasValue && newRecord.Id.Value > 0 ? "Record modified successfully." : "Record saved successfully.")
            : (result.Error?.Code == "DUPLICATE_ENTRY" ? $"Data for Financial Year {actualYear} already exists." : result.Error?.Message ?? "Could not save the record.");

        ViewData["Title"] = "Appendix I - Budget and Expenditure Trends";
        return View("AppendixI", model);
    }

    /// <summary>Bulk-freezes every saved, not-yet-frozen row in the 5-year grid in one action
    /// (the "Freeze Data" button) - distinct from the per-row Freeze in the history table below,
    /// which still freezes a single record at a time.</summary>
    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> FreezeAppendixIBulk(int demandId, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        var demandName = await ResolveDemandNameAsync(session, demandId, ct);
        var model = await BuildAppendixIViewModelAsync(session, demandId, demandName, ct);

        foreach (var row in model.Rows.Where(r => r.Id.HasValue && !r.IsFrozen))
        {
            await _preBudgetClient.FreezeAppendixIAsync(session.Token, row.Id!.Value, ct);
        }

        model = await BuildAppendixIViewModelAsync(session, demandId, demandName, ct);
        model.StatusMessage = "Budget and Expenditure Trends data frozen.";

        ViewData["Title"] = "Appendix I - Budget and Expenditure Trends";
        return View("AppendixI", model);
    }

