    /// <summary>
    /// Export dropdown (2026-09-08, extended to Appendix II from the VI-A..E design) - PDF/Excel/
    /// CSV, same TabularReportDto/_reportingClient shape as ExportAppendixVIA.
    /// </summary>
    [HttpGet]
    public async Task<IActionResult> ExportAppendixII(int demandId, string format, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        var (demandNo, demandName) = await ResolveDemandNoAndNameAsync(session, demandId, ct);
        var model = await BuildAppendixIIViewModelAsync(session, demandId, demandName, ct);

        // Client requirement 2026-09-18: export must match the government circular's own
        // Appendix-II layout exactly (screenshot supplied) - a bordered 3-line header block
        // ("{DemandNo}. {DemandName}" / "Appendix II" / "{Appendix full name}") instead of the
        // Title+Subtitle theme every other appendix export uses, "(In crore of Rupees)" instead of
        // "(₹ in crore)", "As per approved QEP" instead of "As per QEP stipulated by MoF", and no
        // ParaNo/Remarks footer lines at all (this screenshot supersedes the 2026-09-17 circular
        // build's header/footer choices for this appendix specifically). The Year column stays
        // short-form ("2024-25") like every other appendix's circular export, fixing a mismatch
        // where this column previously rendered the raw "2026-2027" session value unshortened.
        var appendix = await FindAppendixByCodeAsync(session.Token, session.FinancialYear, "II", ct);

        // Client requirement 2026-09-18: a cell with no underlying data (as opposed to a genuine
        // computed zero/percentage) is passed as null rather than "" - the shared report generators
        // render a null cell as "0.00" in Excel/CSV and "..." in PDF (see ReportGroup.Rows' own doc
        // comment).
        static string? PercentOf(decimal? actuals, decimal? qep)
        {
            if (actuals == null || qep is null or 0m)
            {
                return null;
            }
            return (actuals.Value / qep.Value * 100m).ToString("F2") + "%";
        }

        var r = model.Records.FirstOrDefault();
        var dataRows = new List<string[]>
        {
            new[] { "1st Quarter", r?.Q1ApprovedQep?.ToString("F2")!, r?.Q1Actuals?.ToString("F2")!, PercentOf(r?.Q1Actuals, r?.Q1ApprovedQep)! },
            new[] { "2nd Quarter", r?.Q2ApprovedQep?.ToString("F2")!, r?.Q2Actuals?.ToString("F2")!, PercentOf(r?.Q2Actuals, r?.Q2ApprovedQep)! }
        };
        var totalRow = new ReportTotalRowDto
        {
            Cells = new[] { "Total", (r != null ? r.TotalApprovedQep.ToString("F2") : null)!, (r != null ? r.TotalActuals.ToString("F2") : null)!, PercentOf(r?.TotalActuals, r?.TotalApprovedQep)! }
        };

        var report = new TabularReportDto
        {
            Title = demandNo.HasValue ? $"{demandNo}. {demandName}" : demandName,
            TitleBoxLines = new List<string> { "Appendix II", appendix?.Name ?? "Quarterly Expenditure Plan Progress (on Gross Basis)" },
            UnitNote = "(In crore of Rupees)",
            Columns = new List<string> { FormatFinancialYearShort(model.PriorFinancialYear), "As per approved QEP", "Actuals", "Actuals as % of QEP" },
            CenterAlignedColumns = new List<int> { 0, 1, 2, 3 },
            RightAlignedColumns = new List<int> { 1, 2, 3 },
            Groups = new List<ReportGroupDto> { new() { Rows = dataRows, Totals = new List<ReportTotalRowDto> { totalRow } } },
            FileName = $"AppendixII-{session.UserName}-{DateTime.Now:MMddyyyyHHmmss}"
        };

        var exportResult = format?.ToLowerInvariant() switch
        {
            "excel" => await _reportingClient.ExportExcelAsync(session.Token, report, ct),
            "csv" => await _reportingClient.ExportCsvAsync(session.Token, report, ct),
            _ => await _reportingClient.ExportPdfAsync(session.Token, report, ct)
        };

        if (!exportResult.IsSuccess || exportResult.Data == null)
        {
            TempData["ErrorMessage"] = exportResult.Error?.Message ?? "Could not generate the export. Please try again.";
            return await AppendixEntry("II", demandId, ct);
        }

        var (contentType, extension) = format?.ToLowerInvariant() switch
        {
            "excel" => ("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "xlsx"),
            "csv" => ("text/csv", "csv"),
            _ => ("application/pdf", "pdf")
        };
        return File(exportResult.Data, contentType, $"{report.FileName}.{extension}");
    }

