    // ---------------------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------------------

    /// <summary>Government-circular abbreviation for the two known M_Category rows shared by
    /// Appendix III/III-B/IV's Category grouping ("Central Sector Schemes/Projects" -> "CS",
    /// "Centrally Sponsored Schemes" -> "CSS") - added 2026-09-18. The live CategoryName text has
    /// no abbreviation of its own (confirmed against the actual M_Category rows), and the circular
    /// always shows the group heading/Total-row label suffixed with it (e.g. "Centrally Sponsored
    /// Schemes (CSS)", "Total (CS)"). Falls back to the full category name for anything else,
    /// rather than guessing an abbreviation for a category this mapping doesn't know about.</summary>
    private static string CategoryAbbreviation(string? categoryName) => categoryName switch
    {
        "Centrally Sponsored Schemes" => "CSS",
        "Central Sector Schemes/Projects" or "Central Sector Schemes" => "CS",
        _ => categoryName ?? "Uncategorized"
    };

    /// <summary>Full group-heading text for a report section grouped by Category - "{Name} ({Abbrev})"
    /// when a known abbreviation exists, otherwise just the plain category name (never a
    /// redundant "Foo (Foo)" for an unmapped category).</summary>
    private static string CategoryHeading(string? categoryName)
    {
        var abbreviation = CategoryAbbreviation(categoryName);
        var name = categoryName ?? "Uncategorized";
        return abbreviation == name ? name : $"{name} ({abbreviation})";
    }

    private async Task<string> ResolveDemandNameAsync(UbisSessionData session, int demandId, CancellationToken ct)
    {
        var (demandNo, demandName) = await ResolveDemandNoAndNameAsync(session, demandId, ct);
        return demandNo.HasValue ? $"{demandNo} - {demandName}" : demandName;
    }

    /// <summary>Raw DemandNo/DemandName pieces (via vw_Demand, same source ResolveDemandNameAsync
    /// itself uses) for export headers that need a different join than the standard "{No} -
    /// {Name}" - added 2026-09-18 for Appendix II's circular format, which uses "{No}. {Name}".</summary>
    private async Task<(int? DemandNo, string DemandName)> ResolveDemandNoAndNameAsync(UbisSessionData session, int demandId, CancellationToken ct)
    {
        var demandsResult = await _aimClient.GetMyDemandsAsync(session.Token, session.FinancialYear, ct);
        var match = demandsResult.Data?.Demands.FirstOrDefault(d => d.DemandId == demandId);
        return match != null ? (match.DemandNo, match.DemandName) : (null, $"Demand {demandId}");
    }

    private async Task<PreBudgetAppendixDto?> FindAppendixByCodeAsync(string bearerToken, string financialYear, string code, CancellationToken ct)
    {
        var result = await _preBudgetClient.GetAppendicesAsync(bearerToken, financialYear, ct);
        return result.Data?.FirstOrDefault(a => string.Equals(a.Code, code, StringComparison.OrdinalIgnoreCase));
    }

    /// <summary>
    /// Populates the shared freeze/target-date-expiry fields on any AppendixBaseViewModel-derived
    /// model (client review 2026-08-05, items 2/3/8): looks up this Demand+Appendix+FY's row from
    /// the Select-Demand-and-Appendix status list and copies its IsFrozen/IsTargetDateExpired flags
    /// across. Every appendix builder should call this right before returning its view model.
    /// </summary>
    private async Task ApplyFreezeStatusAsync(AppendixBaseViewModel model, UbisSessionData session, int demandId, string code, CancellationToken ct)
    {
        model.AppendixCode = code;

        var statusResult = await _preBudgetClient.GetAppendicesWithStatusAsync(session.Token, demandId, session.FinancialYear, ct);
        var match = statusResult.Data?.FirstOrDefault(a => string.Equals(a.Code, code, StringComparison.OrdinalIgnoreCase));
        if (match == null)
        {
            return;
        }

        model.IsAppendixFrozen = match.IsFrozen;
        model.IsTargetDateExpired = match.IsTargetDateExpired;
        model.IsNilSubmitted = match.IsNilSubmitted;
        model.AppendixId = match.AppendixId;
        model.Remarks = match.Remarks;
        model.ParaNo = match.ParaNo;
    }

    /// <summary>Returns <paramref name="count"/> financial-year strings ending at (and including)
    /// <paramref name="currentFinancialYear"/>, oldest first - e.g. for "2026-2027" and count 5:
    /// "2022-2023", "2023-2024", "2024-2025", "2025-2026", "2026-2027". Includes the current year
    /// deliberately - standard FRS "Budget and Expenditure Trends" practice shows the current
    /// year's BE/RE alongside the preceding years' actuals, and (2026-07-29) excluding it made
    /// every existing real record - which was naturally entered under the current year - invisible
    /// in both the entry grid and the history table below it.</summary>
    private static List<string> GetPrecedingFinancialYears(string currentFinancialYear, int count)
    {
        var years = new List<string>();
        var parts = currentFinancialYear?.Split('-');
        if (parts == null || parts.Length != 2 || !int.TryParse(parts[0], out var startYear))
        {
            return years;
        }

        for (var i = count - 1; i >= 0; i--)
        {
            years.Add($"{startYear - i}-{startYear - i + 1}");
        }

        return years;
    }

    /// <summary>"2026-2027" -&gt; "2026-27", matching the government circular's own short year
    /// format (client requirement 2026-09-17, Appendix I export). Falls back to the input
    /// unchanged if it isn't in the expected "YYYY-YYYY" shape.</summary>
    private static string FormatFinancialYearShort(string financialYear)
    {
        var parts = financialYear?.Split('-');
        if (parts == null || parts.Length != 2 || parts[1].Length != 4)
        {
            return financialYear ?? string.Empty;
        }

        return $"{parts[0]}-{parts[1][2..]}";
    }

    /// <summary>Fetches each of the 5 preceding-years' records individually (the PreBudget API
    /// filters strictly by exact FinancialYear per call, so there's no single "all years" query)
    /// and builds both the editable 5-year grid and the read-only history table from the same
    /// data - this is deliberately scoped to just those 5 years per the approved design, not full
    /// all-time history.</summary>
    private async Task<AppendixIViewModel> BuildAppendixIViewModelAsync(UbisSessionData session, int demandId, string demandName, CancellationToken ct)
    {
        var rows = new List<AppendixIYearRowViewModel>();
        var records = new List<AppendixBudgetExpenditureTrendDto>();

        // Client review 2026-08-06 ("Actual Year" terminology): Appendix I's 5-year grid runs
        // Actual Year-4..Actual Year, where Actual Year = Current FY - 2 (e.g. session FY
        // 2026-2027 -> Actual Year 2024-2025 -> grid 2020-2021..2024-2025) - not the session's
        // own current/budget FY. GetPrecedingFinancialYears(cur, 3).First() = cur-2 = Actual Year.
        var actualYear = GetPrecedingFinancialYears(session.FinancialYear, 3).FirstOrDefault() ?? session.FinancialYear;

        foreach (var year in GetPrecedingFinancialYears(actualYear, 5))
        {
            var result = await _preBudgetClient.GetAppendixIAsync(session.Token, demandId, year, ct);
            // Client requirement 2026-09-18: if a Demand somehow has more than one Appendix I row
            // for the same year (data-quality artifact, not a normal flow - CreateRecord blocks a
            // second row per Demand+FinancialYear going forward), show the last-entered one
            // (max Id), not whatever order the API happens to return. A year with no row at all
            // still falls through to the "no data" branch below, which already renders "0.00" for
            // every column via each cell's own ?? "0.00" fallback - no separate change needed there.
            var existing = result.Data?.OrderByDescending(r => r.Id).FirstOrDefault();

            if (existing != null)
            {
                records.Add(existing);

                // Reverted 2026-08-04 (client requirement): every year's entry boxes always show
                // that year's saved values now - only the current filing year's row stays editable
                // (AppendixI.cshtml disables the other 4 rows' inputs based on IsCurrentYear
                // below). Disabled inputs don't post back, so SaveAppendixI's existing
                // "skip a row with no submitted values" check already leaves locked rows alone on
                // submit with no further backend change needed.
                rows.Add(new AppendixIYearRowViewModel
                {
                    FinancialYear = year,
                    Id = existing.Id,
                    IsFrozen = existing.IsFrozen,
                    IsCurrentYear = year == actualYear,
                    RevenueBE = existing.RevenueBE,
                    RevenueRE = existing.RevenueRE,
                    RevenueActuals = existing.RevenueActuals,
                    RevenueActualsUptoSept = existing.RevenueActualsUptoSept,
                    CapitalBE = existing.CapitalBE,
                    CapitalRE = existing.CapitalRE,
                    CapitalActuals = existing.CapitalActuals,
                    CapitalActualsUptoSept = existing.CapitalActualsUptoSept
                });
            }
            else
            {
                // Fixed 2026-09-09 (found while wiring the new Add-gating check): this branch
                // compared against session.FinancialYear instead of actualYear, so a blank
                // not-yet-saved ActualYear row was wrongly flagged IsCurrentYear=false (the "else"
                // branch above already got this right). Harmless in practice so far - ActualYear is
                // 2 years behind the session's filing year, so by the time a cycle reaches that
                // year it already has a saved (often frozen) record and hits the "existing != null"
                // branch instead - but the new single-source-of-truth Add-gating check below needs
                // this to be correct in every case, not just the common one.
                rows.Add(new AppendixIYearRowViewModel { FinancialYear = year, IsCurrentYear = year == actualYear });
            }
        }

        var model = new AppendixIViewModel
        {
            DemandId = demandId,
            DemandName = demandName,
            FinancialYear = session.FinancialYear,
            Records = records,
            Rows = rows,
            ActualYear = actualYear
        };
        model.NewRecord.FinancialYear = actualYear;
        await ApplyFreezeStatusAsync(model, session, demandId, "I", ct);
        return model;
    }

