    // "Page sometimes automatically refreshes and I lose my Demand/Appendix selection" (client
    // report, 2026-08-25) - root cause: this page never does a real page navigation, every
    // Submit/Save/cascade round trip is a fetch() into #partialViewContainer (see OnActionExecuted's
    // own doc comment above). A RedirectToAction here was silently followed by fetch() (redirects
    // are followed transparently by default) all the way to the full Login page's HTML - including
    // its own header/sidebar - which then got stuffed into that small container, looking exactly
    // like an unexplained "page refresh" that wiped whatever was on screen. Same bug class as the
    // FreezeAppendixIA fix noted elsewhere in this file ("OnActionExecuted only fragment-izes a
    // ViewResult, not a RedirectResult"), just triggered by session expiry instead of a Freeze
    // action. For an AJAX request, return 401 instead so the client JS can do a REAL, visible
    // `window.location.href` navigation to Login (see pre-budget-meeting.js's response handling).
    private async Task<IActionResult> ExpiredSessionRedirectAsync()
    {
        await HttpContext.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);
        if (IsAjaxRequest())
        {
            return Unauthorized();
        }
        return RedirectToAction("Login", "User", new { area = "" });
    }

    // FR-004: Autonomous Master for Appendix VI-C/VI-E. Access is restricted to exactly two roles
    // (client requirement, 2026-08-10): Administrator (creates/maintains the master directly, via
    // the Add form below) and "Single Demand Users" (this system's Ministry User equivalent - the
    // FRS's generic "Ministry User"/"Budget Division User"/"ABO/DS/Director User" wording doesn't
    // match any literal role name here, and the client narrowed access to just these two, tighter
    // than the FRS's three). Both the menu (RoleFunctionMappingSeedConfiguration, FunctionId 347)
    // and this action must independently enforce this - menu visibility alone doesn't stop direct
    // URL access. AutonomousBodiesController's own admin checks (AutonomousBodyAdminRoleOptions)
    // remain the authoritative server-side gate on the actual write actions; the checks here are
    // this MVC layer's independent enforcement of page-level access, not a UI-only convenience.
    private static readonly string[] AutonomousBodyAdminRoleNames = { "Administrator", "Super Admin" };
    private static readonly string[] AutonomousMasterPageRoleNames = { "Administrator", "Super Admin", "Single Demand Users" };

    private static readonly TimeSpan AutonomousBodiesCacheTtl = TimeSpan.FromMinutes(15);

    private static string AutonomousBodiesCacheKey(int demandId, string financialYear) =>
        $"ubis:autonomous-bodies:{demandId}:{financialYear}";

    [HttpGet]
    public async Task<IActionResult> AutonomousMasterforAppendixVICandVIE(int? demandId, CancellationToken ct)
    {
        ViewData["Title"] = "Autonomous Master for Appendix VI C and VI E";
        ViewData["Breadcrumb"] = "Pre Budget Meeting / Pre Budget Meeting / Autonomous Master for Appendix VI C and VI E";

        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        if (!AutonomousMasterPageRoleNames.Contains(session.RoleName, StringComparer.OrdinalIgnoreCase))
        {
            return Forbid();
        }

        var model = new AutonomousMasterViewModel
        {
            FinancialYear = session.FinancialYear,
            SelectedDemandId = demandId,
            CanReview = AutonomousBodyAdminRoleNames.Contains(session.RoleName, StringComparer.OrdinalIgnoreCase)
        };

        var demandsResult = await _aimClient.GetMyDemandsAsync(session.Token, session.FinancialYear, ct);
        if (demandsResult.IsSuccess && demandsResult.Data != null)
        {
            model.Demands = demandsResult.Data.Demands;
        }

        // Client requirement 2026-08-31: "For Single Demand User, there is only single demand so
        // show in label not in dropdown ... and its associated grid show during page load" - same
        // Demands.Count == 1 condition PreBudgetDataandReport.cshtml already uses for its own
        // Single-Demand-User label. Auto-selects the sole Demand server-side (this page is a plain
        // full-page GET, not the AJAX cascade PreBudgetDataandReport uses, so there's no client-side
        // bootstrap to mirror - selecting it here is what makes the grid/forms below render
        // immediately on page load instead of needing an explicit pick first).
        if (!demandId.HasValue && model.Demands.Count == 1)
        {
            demandId = model.Demands[0].DemandId;
            model.SelectedDemandId = demandId;
        }

        if (demandId.HasValue)
        {
            var bodiesResult = await _preBudgetClient.GetAutonomousBodiesAsync(session.Token, demandId.Value, session.FinancialYear, ct);
            if (bodiesResult.IsSuccess && bodiesResult.Data != null)
            {
                model.AutonomousBodies = bodiesResult.Data;

                // Client requirement 2026-08-10: every existing Autonomous Body for this Demand is
                // cached in Redis on page load, so the Add/Request forms' duplicate-name check
                // (CheckAutonomousBodyNameExists below) can be answered from cache instead of a DB
                // round trip on every keystroke.
                await _cache.SetAsync(AutonomousBodiesCacheKey(demandId.Value, session.FinancialYear), model.AutonomousBodies, AutonomousBodiesCacheTtl, ct);
            }
        }

        if (model.CanReview)
        {
            var pendingResult = await _preBudgetClient.GetPendingAutonomousBodyRequestsAsync(session.Token, ct);
            if (pendingResult.IsSuccess && pendingResult.Data != null)
            {
                model.PendingRequests = pendingResult.Data;
            }
        }

        return View(model);
    }

    /// <summary>Direct add - matches the legacy "Add Autonomous/Grantee Name" form. Originally
    /// Administrator-only; opened up to every AutonomousMasterPageRoleNames role (client
    /// requirement, 2026-08-31: "it should not request Autonomous Body, it should add it" - Single
    /// Demand Users now save directly through this same action instead of the old Request flow).
    /// Server-side role check is authoritative in AutonomousBodiesController
    /// (AutonomousBodyCreatorRoleOptions); this MVC-layer check just avoids a pointless round trip
    /// for a role that would be rejected anyway.</summary>
    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> CreateAutonomousBody(int demandId, string name, string? hName, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        if (!AutonomousMasterPageRoleNames.Contains(session.RoleName, StringComparer.OrdinalIgnoreCase))
        {
            return Forbid();
        }

        var result = await _preBudgetClient.CreateAutonomousBodyAsync(session.Token, new CreateAutonomousBodyDto
        {
            DemandId = demandId,
            FinancialYear = session.FinancialYear,
            Name = name,
            HName = hName
        }, ct);

        if (result.IsSuccess && result.Data != null)
        {
            // Client requirement 2026-08-10: the new entry is added to the Redis cache immediately,
            // not just left to the next page load's re-fetch, so the duplicate-name check reflects
            // it right away (e.g. a second admin browsing the same Demand in another tab).
            var cacheKey = AutonomousBodiesCacheKey(demandId, session.FinancialYear);
            var cached = await _cache.GetAsync<List<AutonomousBodyDto>>(cacheKey, ct) ?? new List<AutonomousBodyDto>();
            cached.Add(result.Data);
            await _cache.SetAsync(cacheKey, cached, AutonomousBodiesCacheTtl, ct);
        }

        // Client requirement 2026-08-31: "show MessageBox in Dialog: Title: Save Record. Text:
        // 'Autonomous Body Name is Saved Successfully'" - exact wording, rendered as the standard
        // dialogs.js modal by the view (see autonomous-master.js) instead of the old inline banner.
        TempData["AutonomousMasterStatus"] = result.IsSuccess
            ? "Autonomous Body Name is Saved Successfully"
            : (result.Error?.Message ?? "Could not add the Autonomous Body.");
        TempData["AutonomousMasterStatusIsError"] = !result.IsSuccess;
        TempData["AutonomousMasterFocusName"] = true;

        return RedirectToAction(nameof(AutonomousMasterforAppendixVICandVIE), new { demandId });
    }

    /// <summary>
    /// AJAX-only, client requirement 2026-08-10: the Add/Request forms call this on the Name and
    /// HName fields to warn about a duplicate before submitting, answered from the Redis cache
    /// AutonomousMasterforAppendixVICandVIE populated on page load (falls back to a live fetch -
    /// and re-caches - on a cache miss, e.g. if the page has been open longer than the cache TTL).
    /// Case-insensitive, trimmed - matches how a human would judge "the same name". `field` selects
    /// which of the existing bodies' columns to compare against - "Name" (English, default) or
    /// "HName" (Hindi) - since the two are independent duplicate checks, not one combined check.
    /// </summary>
    [HttpGet]
    public async Task<IActionResult> CheckAutonomousBodyNameExists(int demandId, string name, string? field, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return Unauthorized();
        }

        var trimmedName = (name ?? string.Empty).Trim();
        if (trimmedName.Length == 0)
        {
            return Json(new { exists = false });
        }

        var checkHindi = string.Equals(field, "HName", StringComparison.OrdinalIgnoreCase);

        var cacheKey = AutonomousBodiesCacheKey(demandId, session.FinancialYear);
        var cached = await _cache.GetAsync<List<AutonomousBodyDto>>(cacheKey, ct);
        if (cached == null)
        {
            var bodiesResult = await _preBudgetClient.GetAutonomousBodiesAsync(session.Token, demandId, session.FinancialYear, ct);
            cached = bodiesResult.Data ?? new List<AutonomousBodyDto>();
            await _cache.SetAsync(cacheKey, cached, AutonomousBodiesCacheTtl, ct);
        }

        var exists = checkHindi
            ? cached.Any(b => !string.IsNullOrEmpty(b.HName) && string.Equals(b.HName.Trim(), trimmedName, StringComparison.OrdinalIgnoreCase))
            : cached.Any(b => string.Equals(b.Name?.Trim(), trimmedName, StringComparison.OrdinalIgnoreCase));
        return Json(new { exists });
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> RequestAutonomousBody(int demandId, string requestedName, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        var result = await _preBudgetClient.RequestNewAutonomousBodyAsync(session.Token, new CreateAutonomousBodyRequestDto
        {
            DemandId = demandId,
            FinancialYear = session.FinancialYear,
            RequestedName = requestedName
        }, ct);

        TempData["AutonomousMasterStatus"] = result.IsSuccess
            ? "Request submitted — an Administrator will review it."
            : (result.Error?.Message ?? "Could not submit the request.");
        TempData["AutonomousMasterStatusIsError"] = !result.IsSuccess;

        return RedirectToAction(nameof(AutonomousMasterforAppendixVICandVIE), new { demandId });
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> ReviewAutonomousBodyRequest(int requestId, int demandId, bool approve, string? code, string? reviewRemarks, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        var result = await _preBudgetClient.ReviewAutonomousBodyRequestAsync(session.Token, requestId, new ReviewAutonomousBodyRequestDto
        {
            Approve = approve,
            Code = code,
            ReviewRemarks = reviewRemarks
        }, ct);

        if (result.IsSuccess && approve)
        {
            // Approving also creates a real AutonomousBody row (in PreBudget, via AIM's/PreBudget's
            // own ReviewRequestAsync) - but the response here is the request DTO, not the created
            // body's full shape (Id/Code), so invalidate rather than reconstruct a partial cache
            // entry. The GET action re-fetches and re-caches on next load.
            await _cache.RemoveAsync(AutonomousBodiesCacheKey(demandId, session.FinancialYear), ct);
        }

        TempData["AutonomousMasterStatus"] = result.IsSuccess
            ? (approve ? "Request approved." : "Request rejected.")
            : (result.Error?.Message ?? "Could not review the request.");
        TempData["AutonomousMasterStatusIsError"] = !result.IsSuccess;

        return RedirectToAction(nameof(AutonomousMasterforAppendixVICandVIE), new { demandId });
    }

    // FR-003: RE Data Remarks. Read/write are both role-gated server-side (RemarksController via
    // RemarkRoleOptions) — CanPostRemark here just hides the composer for everyone else.
    private static readonly string[] RemarkAllowedRoleNames = { "Budget Division", "ABO-DS-Director", "Administrator" };

    // Client instruction 2026-09-21: on the Appendix IV/IV-A/IV-B grids and edit drawers, "Single
    // Demand Users" (Ministry side) only need to see Remarks (Ministry); "ABO-DS-Director" has the
    // same access as Budget Division and Section User for this purpose, so all three only need to
    // see Remarks (Budget Div) - none of the three should see the other side's internal remarks.
    // Distinct from RemarkAllowedRoleNames above (that one gates FR-003's separate RE Data Remarks
    // composer and includes Administrator; this one is grid-column visibility on a different
    // feature and deliberately does not restrict Administrator/other roles, who keep seeing both
    // columns per ResolveRemarksColumnVisibility's own default-true fallback).
    private static readonly string[] BudgetSideRemarksRoleNames = { "Budget Division", "ABO-DS-Director", "Section User" };

    private static void ApplyRemarksColumnVisibility(AppendixBaseViewModel model, string? roleName)
    {
        if (string.Equals(roleName, "Single Demand Users", StringComparison.OrdinalIgnoreCase))
        {
            model.ShowRemarksBudgetColumn = false;
        }
        else if (BudgetSideRemarksRoleNames.Contains(roleName, StringComparer.OrdinalIgnoreCase))
        {
            model.ShowRemarksMinistryColumn = false;
        }
    }

    [HttpGet]
    public async Task<IActionResult> REDataRemarks(int? demandId, int? appendixId, CancellationToken ct)
    {
        ViewData["Title"] = "RE Data Remarks";
        ViewData["Breadcrumb"] = "Pre Budget Meeting / Pre Budget Meeting / RE Data Remarks";

        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        var model = new REDataRemarksViewModel
        {
            FinancialYear = session.FinancialYear,
            SelectedDemandId = demandId,
            SelectedAppendixId = appendixId,
            CanPostRemark = RemarkAllowedRoleNames.Contains(session.RoleName, StringComparer.OrdinalIgnoreCase)
        };

        var demandsResult = await _aimClient.GetMyDemandsAsync(session.Token, session.FinancialYear, ct);
        if (demandsResult.IsSuccess && demandsResult.Data != null)
        {
            model.Demands = demandsResult.Data.Demands;
        }

        if (demandId.HasValue)
        {
            var appendicesResult = await _preBudgetClient.GetAppendicesAsync(session.Token, session.FinancialYear, ct);
            if (appendicesResult.IsSuccess && appendicesResult.Data != null)
            {
                model.Appendices = appendicesResult.Data;
            }
        }

        if (demandId.HasValue && appendixId.HasValue)
        {
            var remarksResult = await _preBudgetClient.GetRemarksAsync(session.Token, demandId.Value, appendixId.Value, session.FinancialYear, ct);
            if (remarksResult.IsSuccess && remarksResult.Data != null)
            {
                model.Remarks = remarksResult.Data;
            }
            else
            {
                model.StatusIsError = true;
                model.StatusMessage = remarksResult.Error?.Message ?? "Could not load remarks for the selected Appendix.";
            }
        }

        return View(model);
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> AddRemark(int demandId, int appendixId, string remarkText, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        if (!string.IsNullOrWhiteSpace(remarkText))
        {
            await _preBudgetClient.CreateRemarkAsync(session.Token, new CreatePreBudgetRemarkDto
            {
                DemandId = demandId,
                AppendixId = appendixId,
                FinancialYear = session.FinancialYear,
                RemarkText = remarkText
            }, ct);
        }

        return RedirectToAction(nameof(REDataRemarks), new { demandId, appendixId });
    }

